INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-02' FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Peppol 4-corner (B2G live; B2B proposed 2028-2029)', 'This deep-dive page reflects publicly available technical guidance as of August 2026 and is provided for general awareness, not legal or tax advice. The proposed B2B mandate remains subject to parliamentary approval and could change — confirm current requirements directly with CTIE / eFacturation.lu or your chosen Peppol Access Point before building an integration.', 'Luxembourg built its e-invoicing programme in two distinct phases: a Peppol-based B2G mandate rolled out gradually by company size and completed in 2023, followed by a proposed extension to domestic B2B transactions using the same network, still awaiting parliamentary approval.', 'Luxembourg leans on the standard EU Peppol profile rather than a bespoke national format, with a government web portal available as a manual fallback for smaller B2G suppliers.', 'There''s no separate Luxembourg clearance platform — Peppol has carried B2G traffic from the start, and the proposed B2B mandate would extend the same four-corner network to domestic transactions.', 'Getting compliant centres on confirming your Peppol identity and archiving setup — the guichet.lu / eFacturation.lu portal exists specifically so smaller suppliers aren''t blocked by a lack of Peppol-ready software.', 'Luxembourg hasn''t published a fixed fine schedule for e-invoicing non-compliance — enforcement today runs through invoice rejection and public-procurement consequences rather than automatic penalties.', 'Luxembourg''s B2G e-invoicing mandate has been fully in force since March 2023, phased in by company size under Peppol BIS Billing 3.0. A draft law approved in July 2026 would extend mandatory e-invoicing to domestic B2B transactions in phases from 2028-2029, though this is not yet enacted.', '📜' FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '4-corner', 'Peppol model');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Luxembourg';
