INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '10 yrs', 'Archive requirement');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2023', 'B2G fully in force');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2029', 'Proposed B2B complete');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Default format", "Peppol BIS Billing 3.0 (UBL 2.1)"], ["European semantic model", "EN 16931"], ["National CIUS", "None — uses Peppol BIS CIUS directly"], ["Manual alternative", "guichet.lu / eFacturation.lu web form (structured data entry or file upload)"]]', 'Luxembourg doesn''t require a bespoke national format for public-sector invoicing — the same Peppol BIS Billing 3.0 profile used across the EU is fully compliant, and a government web portal covers suppliers who don''t yet have Peppol-connected software.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Business identifiers', '[["Peppol ID scheme", "9938 (Luxembourg VAT number)"], ["Format example", "iso6523-actorid-upis::9938:LU + 8 digits"], ["Directory lookup", "Peppol Directory"]]', 'Scheme 9938 ties your Peppol identity directly to your Luxembourg VAT number, so businesses already registered for VAT don''t need a separate ID to become discoverable on the network.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory invoice fields', '[["Header", "Unique invoice number, ISO 8601 issue date, currency, PO/contract reference"], ["Party data", "Legal name, VAT no., registered address, Peppol Participant ID"], ["Line level", "VAT category code, rate, quantity, unit price, line total"]]', 'Public bodies can reject non-compliant e-invoices outright, so missing or mismatched fields — particularly the contract reference — are the most common cause of payment delay, not outright fines.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Archiving', '[["Retention period", "10 years minimum"], ["What to keep", "Original structured invoice + transmission/processing records"]]', 'Luxembourg''s 10-year retention period is longer than several neighbouring markets — factor this into any Peppol Access Point contract, since you''ll need continued access to historical invoices well after you might otherwise switch providers.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Network model', '[["B2G model", "Peppol 4-corner (decentralised)"], ["Manual channel", "guichet.lu / eFacturation.lu portal"], ["Government authority", "CTIE (Government IT Centre) / eFacturation.lu"]]', 'Unlike some peers, Luxembourg never built a separate central clearing platform for B2G — Peppol has been the backbone from the start, with the government portal there only as a manual fallback for suppliers without Peppol-ready software.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Access Point connectivity', '[["Requirement", "Certified Peppol Access Point (or manual guichet.lu entry)"], ["Common providers", "Most Peppol-enabled ERPs and accounting platforms support Luxembourg out of the box"], ["Validation point", "Schematron checks run at the Access Point before network entry"]]', 'If you''re a small supplier with only occasional public contracts, the manual guichet.lu route may be simpler than onboarding a full Access Point — reassess once volume grows.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Coming: proposed B2B mandate', '[["Model", "Peppol four-corner (same network as B2G)"], ["Scope", "Domestic B2B transactions between Luxembourg-established businesses"], ["Legal status", "Draft law approved by Council of Government, 17 July 2026 — not yet enacted"]]', 'This is still a proposal, not law — track its progress through Parliament before treating any 2028/2029 date as fixed.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ No fixed fine schedule (B2G)', NULL, NULL, 'Non-compliant B2G invoices are typically rejected or returned unpaid by the receiving public body rather than triggering an automatic fine — but persistent non-compliance can lead to contract disputes or administrative consequences under public procurement law.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🌍 No domestic real-time reporting planned', NULL, NULL, 'Luxembourg''s e-invoicing push is about structured invoice exchange, not tax-authority reporting — no domestic continuous transaction control or e-reporting layer is currently planned, unlike Belgium''s 2028 e-reporting build-out.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📋 B2B is still a draft', NULL, NULL, 'The July 2026 Council of Government approval is a real step, but the B2B mandate remains subject to parliamentary approval before the 2028/2029 dates take effect.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your Luxembourg VAT number', 'This is also your Peppol identifier (scheme 9938) for B2G invoicing, so check it''s correct and current before registering with an Access Point.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose a certified Peppol Access Point', 'Pick a standalone provider or confirm your existing accounting/ERP software already includes Peppol connectivity.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Use guichet.lu / eFacturation.lu if you''re not Peppol-ready yet', 'The government web form lets you enter or upload B2G invoices manually while you get proper Peppol connectivity set up.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Test invoice generation against BIS Billing 3.0', 'Validate correct VAT category codes, unique invoice numbers, and the public-sector contract reference — mismatches here are the most common cause of rejection.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Set up compliant 10-year archiving', 'Confirm your retention solution meets Luxembourg''s 10-year minimum for both the original structured invoice and its transmission/processing records.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you trade domestically B2B, start monitoring the draft law', 'The proposed 2028 receipt deadline would use the same Peppol infrastructure as B2G — getting B2G-ready now puts you ahead of it.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://ec.europa.eu/digital-building-blocks/sites/spaces/DIGITAL/pages/467108893/eInvoicing+in+Luxembourg', 0 FROM countries WHERE name_en = 'Luxembourg';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'EU Digital Building Blocks — Luxembourg');
